def erase_overlap_intervals(intervals):
    if not intervals:
        return 0
    sorted_intervals = sorted(intervals, key=lambda pair: pair[1])
    removed = 0
    last_end = float('-inf')
    for start, end in sorted_intervals:
        if start >= last_end:
            last_end = end
        else:
            removed += 1
    return removed

